                </div>
              )}
            </div>
          </div>
        </div>
      );
    };

    const ThreadHierarchy = ({ 
      parentMsgId, 
      threads, 
      messages, 
      compactMode,
      onNavigateToThread,
      onOpenThread,
      onToggleThread,
      onResolveThread,
      onInviteToThread,
      getThreadMessages,
      getSiblingThreads,
      getChildThreads,
      onSendMessage
    }) => {
      const mainThreads = threads.filter(t => t.parentMsgId === parentMsgId);

      return (
        <div className="space-y-4">
          {mainThreads.map(thread => (
            <ThreadCard
              key={thread.id}
              thread={thread}
              threads={threads}
              messages={messages}
              compactMode={compactMode}
              onNavigateToThread={onNavigateToThread}
              onOpenThread={onOpenThread}
              onToggleThread={onToggleThread}
              onResolveThread={onResolveThread}
              onInviteToThread={onInviteToThread}
              getThreadMessages={getThreadMessages}
              getSiblingThreads={getSiblingThreads}
              getChildThreads={getChildThreads}
              level={0}
              onSendMessage={onSendMessage}
            />
          ))}
        </div>
      );
