                  <div className="text-center text-sm text-blue-600">
                    +{threadMessages.length - 2} more messages
                  </div>
                )}

                {threadMessages.length === 0 && (
                  <div className="text-center py-4 text-gray-500 text-sm">
                    💬 Click "Open" to start discussion
                  </div>
